package ama.storage;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static ama.storage.Task11B2ExactRetryOracle.*;
/** Full nineteen-table preservation boundary; selected new rows are further checked by phase assertions. */
final class Task11B3LifecycleOracle {
 static final Map<String,Set<String>> ROOT_FIELDS=Map.of("meeting",Set.of("stage","updated_at"),"publication",Set.of("state","revision"),"external_operation",Set.of("state","current_execution_no","reconcile_epoch","reconcile_owner","reconcile_expires_at","next_check_at","last_error"));
 static void preserved(Map<String,List<Map<String,Object>>> before,Map<String,List<Map<String,Object>>> after,Map<String,List<String>> keys,String meeting,String publication,String operation,Set<String> tasks,Set<String> executions){
  assertEquals(new HashSet<>(Task11B3PreparedFixture.BUSINESS),before.keySet());assertEquals(before.keySet(),after.keySet());assertEquals(before.keySet(),keys.keySet());
  for(String table:before.keySet()){
   var actual=new HashMap<List<Object>,Map<String,Object>>();for(var row:after.get(table))assertNull(actual.put(Task11B3LocalOracle.identity(row,keys.get(table)),row),"Duplicate primary identity: "+table);
   for(var old:before.get(table)){
    var found=actual.remove(Task11B3LocalOracle.identity(old,keys.get(table)));assertNotNull(found,"Protected predecessor missing: "+table);assertEquals(old.keySet(),found.keySet(),table+" field set");
    String root=switch(table){case "meeting"->meeting;case "publication"->publication;case "external_operation"->operation;default->null;};
    if(root!=null&&root.equals(old.get("id")))equal(Task11B3LocalOracle.without(old,ROOT_FIELDS.get(table)),Task11B3LocalOracle.without(found,ROOT_FIELDS.get(table)));
    else if(table.equals("task_outbox_sequence"))equal(Task11B3LocalOracle.without(old,Set.of("next_id")),Task11B3LocalOracle.without(found,Set.of("next_id")));else equal(old,found);
   }
   for(var row:actual.values())switch(table){
    case "durable_task"->assertTrue(tasks.contains(row.get("id")),"Foreign task addition");
    case "external_execution"->assertTrue(executions.contains(row.get("id"))&&tasks.contains(row.get("task_id")),"Foreign execution addition");
    case "publication_submission"->assertTrue(tasks.contains(row.get("task_id"))&&publication.equals(row.get("publication_id")),"Foreign submission addition");
    case "task_attempt"->assertTrue(tasks.contains(row.get("task_id")),"Foreign attempt addition");
    case "publication_attempt"->assertTrue(publication.equals(row.get("publication_id")),"Foreign publication attempt");
    case "task_outbox"->{assertTrue(tasks.contains(row.get("task_id")));assertEquals(meeting,row.get("subject_id"));assertEquals("MEETING",row.get("subject_kind"));assertEquals("PUBLICATION",row.get("reference_kind"));assertEquals(publication,row.get("reference_id"));}
    case "audit_event"->assertEquals(meeting,row.get("resource_id"));
    case "idempotency_record"->{assertEquals(meeting,row.get("resource_id"));assertTrue(Set.of("PUBLICATION_RESUBMIT","PUBLICATION_LOCAL_RECOVERY","PUBLICATION_ZERO_EFFECT_RETRY").contains(row.get("operation")),"Foreign receipt operation");}
    default->fail("Unreleased row addition: "+table);
   }
  }
 }
 static void queryOnlyUnknown(Map<String,List<Map<String,Object>>> before,Map<String,List<Map<String,Object>>> after,Map<String,List<String>> keys,String operation,String execution,String task){
  assertEquals(before.keySet(),after.keySet());for(String table:before.keySet()){
   int added=table.equals("task_outbox")?1:0;assertEquals(before.get(table).size()+added,after.get(table).size(),table+" query-only count");var actual=new HashMap<List<Object>,Map<String,Object>>();for(var row:after.get(table))assertNull(actual.put(Task11B3LocalOracle.identity(row,keys.get(table)),row));
   for(var old:before.get(table)){var found=actual.remove(Task11B3LocalOracle.identity(old,keys.get(table)));assertNotNull(found);assertEquals(old.keySet(),found.keySet());Set<String> allowed=table.equals("external_operation")&&operation.equals(old.get("id"))?Set.of("state","last_error","next_check_at","reconcile_epoch","reconcile_owner","reconcile_expires_at"):table.equals("external_execution")&&execution.equals(old.get("id"))?Set.of("state"):table.equals("task_outbox_sequence")?Set.of("next_id"):Set.of();equal(Task11B3LocalOracle.without(old,allowed),Task11B3LocalOracle.without(found,allowed));}
   if(added==1){assertEquals(1,actual.size());var event=actual.values().iterator().next();assertEquals("EXTERNAL_UNKNOWN",event.get("event_type"));assertEquals(task,event.get("task_id"));assertEquals(integer(before.get("task_outbox_sequence").getFirst().get("next_id")),integer(event.get("sequence_id")));}else assertTrue(actual.isEmpty());
  }
  var old=Task11B3LocalOracle.row(before,"external_operation","id",operation);var now=Task11B3LocalOracle.row(after,"external_operation","id",operation);assertEquals("MARKED",old.get("state"));assertEquals("UNKNOWN",now.get("state"));assertEquals("UNKNOWN_OUTCOME",now.get("last_error"));assertEquals(integer(old.get("reconcile_epoch")).add(java.math.BigInteger.ONE),integer(now.get("reconcile_epoch")));assertEquals("b3-lifecycle-query-child",now.get("reconcile_owner"));assertNotNull(now.get("reconcile_expires_at"));equal(now.get("next_check_at"),now.get("reconcile_expires_at"));assertEquals("UNKNOWN",Task11B3LocalOracle.row(after,"external_execution","id",execution).get("state"));assertEquals("RECONCILING",Task11B3LocalOracle.row(after,"durable_task","id",task).get("state"));assertEquals(integer(before.get("task_outbox_sequence").getFirst().get("next_id")).add(java.math.BigInteger.ONE),integer(after.get("task_outbox_sequence").getFirst().get("next_id")));
 }
 static List<Map<String,Object>> added(Map<String,List<Map<String,Object>>> before,Map<String,List<Map<String,Object>>> after,Map<String,List<String>> keys,String table){var old=new HashSet<List<Object>>();before.get(table).forEach(row->old.add(Task11B3LocalOracle.identity(row,keys.get(table))));return after.get(table).stream().filter(row->!old.contains(Task11B3LocalOracle.identity(row,keys.get(table)))).toList();}
 static void complete(Map<String,List<Map<String,Object>>> before,Map<String,List<Map<String,Object>>> after,Map<String,List<String>> keys,String meeting,String publication,String operation,String owner,List<String> tasks,List<String> executions,List<Sealed> sealed)throws Exception {
  assertEquals(6,tasks.size());assertEquals(6,executions.size());assertEquals(5,sealed.size());for(int n=0;n<5;n++){assertEquals(tasks.get(n),sealed.get(n).task());assertEquals(executions.get(n),sealed.get(n).execution());requireSealed(sealed.get(n),after,keys);}preserved(before,after,keys,meeting,publication,operation,Set.copyOf(tasks),Set.copyOf(executions));var counts=Map.of("durable_task",6,"external_execution",6,"publication_submission",6,"task_attempt",10,"publication_attempt",1,"idempotency_record",9,"audit_event",11,"task_outbox",26);for(String table:before.keySet())assertEquals(before.get(table).size()+counts.getOrDefault(table,0),after.get(table).size(),table+" exact cumulative count");
  var root=Task11B3LocalOracle.row(after,"meeting","id",meeting);assertEquals("PUBLISH_FAILED",root.get("stage"));assertEquals(java.math.BigInteger.valueOf(13),integer(root.get("revision")));var pub=Task11B3LocalOracle.row(after,"publication","id",publication);assertEquals("RUNNING",pub.get("state"));assertEquals(java.math.BigInteger.valueOf(19),integer(pub.get("revision")));var op=Task11B3LocalOracle.row(after,"external_operation","id",operation);assertEquals("UNKNOWN",op.get("state"));assertEquals(integer(Task11B3LocalOracle.row(before,"external_operation","id",operation).get("current_execution_no")).add(java.math.BigInteger.valueOf(6)),integer(op.get("current_execution_no")));assertEquals(integer(Task11B3LocalOracle.row(before,"external_operation","id",operation).get("reconcile_epoch")).add(java.math.BigInteger.valueOf(13)),integer(op.get("reconcile_epoch")));
  int[] attempts={1,1,3,3,1,1};String[] reasons={"EXPIRED_UNMARKED_ABANDONED","EXPIRED_UNMARKED_ABANDONED","PREPARATION_EXHAUSTED","PREPARATION_EXHAUSTED","EXPIRED_UNMARKED_ABANDONED"};
  for(int n=0;n<6;n++){String task=tasks.get(n),execution=executions.get(n);var t=Task11B3LocalOracle.row(after,"durable_task","id",task);assertEquals(n==5?"RECONCILING":"FAILED",t.get("state"));assertEquals(java.math.BigInteger.valueOf(attempts[n]),integer(t.get("attempt")));var e=Task11B3LocalOracle.row(after,"external_execution","id",execution);assertEquals(task,e.get("task_id"));assertEquals(operation,e.get("operation_id"));assertEquals(n==5?"UNKNOWN":"FAILED",e.get("state"));assertEquals(java.math.BigInteger.valueOf(n+3),integer(e.get("execution_no")));var s=Task11B3LocalOracle.row(after,"publication_submission","task_id",task);assertEquals(publication,s.get("publication_id"));assertEquals(java.math.BigInteger.valueOf(n+4),integer(s.get("submission_no")));assertEquals(n==5?"UNDECIDED":"NEVER_MARKED",s.get("local_state"));assertEquals(owner,s.get("requester_id"));assertEquals(e.get("request_manifest"),s.get("request_manifest"));assertEquals(e.get("request_hash"),s.get("execution_request_hash"));
   var a=after.get("task_attempt").stream().filter(row->task.equals(row.get("task_id"))).sorted(Comparator.comparing(row->integer(row.get("attempt")))).toList();assertEquals(attempts[n],a.size());for(int index=0;index<a.size();index++){var row=a.get(index);assertEquals(java.math.BigInteger.valueOf(index+1),integer(row.get("attempt")));if(n==5)assertNull(row.get("ended_at"));else assertNotNull(row.get("ended_at"));}
   if(n<5){assertEquals(reasons[n],s.get("local_reason"));assertEquals(owner,s.get("local_decided_by"));assertEquals(execution,s.get("local_execution_id"));assertEquals(java.math.BigInteger.valueOf(attempts[n]),integer(s.get("local_attempt_no")));assertNull(e.get("marked_at"));assertNull(e.get("task_attempt"));assertEquals("NOT_SENT",e.get("no_effect_basis"));}else{assertNotNull(e.get("marked_at"));assertEquals(java.math.BigInteger.ONE,integer(e.get("task_attempt")));assertNull(e.get("no_effect_basis"));assertNull(s.get("local_decided_at"));}
  }
  var publicationAttempt=added(before,after,keys,"publication_attempt").getFirst();assertEquals(executions.getLast(),publicationAttempt.get("execution_id"));assertEquals(operation,publicationAttempt.get("operation_id"));assertEquals("PENDING",publicationAttempt.get("outcome"));assertEquals("PUBLISH",publicationAttempt.get("kind"));
  var audits=new HashMap<String,Integer>();for(var row:added(before,after,keys,"audit_event")){assertEquals(owner,row.get("actor_id"));assertEquals(meeting,row.get("resource_id"));assertEquals("SUCCEEDED",row.get("result"));assertEquals(java.math.BigInteger.valueOf(13),integer(row.get("revision")));audits.merge((String)row.get("action"),1,Integer::sum);}assertEquals(Map.of("PUBLICATION_RESUBMITTED",6,"PUBLICATION_LOCAL_NEVER_MARKED",5),audits);
  var eventCounts=new HashMap<String,Integer>();var sequences=new TreeSet<java.math.BigInteger>();for(var event:added(before,after,keys,"task_outbox")){eventCounts.merge((String)event.get("event_type"),1,Integer::sum);assertTrue(sequences.add(integer(event.get("sequence_id"))));}assertEquals(Map.of("TASK_ENQUEUED",6,"PUBLICATION_ACCEPTED",6,"TASK_FAILED",5,"PUBLICATION_LOCAL_RECOVERED",3,"TASK_RETRY",3,"TASK_RECONCILING",1,"EXTERNAL_MARKED",1,"EXTERNAL_UNKNOWN",1),eventCounts);var first=integer(before.get("task_outbox_sequence").getFirst().get("next_id"));for(int i=0;i<26;i++)assertTrue(sequences.contains(first.add(java.math.BigInteger.valueOf(i))));assertEquals(first.add(java.math.BigInteger.valueOf(26)),integer(after.get("task_outbox_sequence").getFirst().get("next_id")));
  var receipts=added(before,after,keys,"idempotency_record");for(int n=1;n<=6;n++){String task=tasks.get(n-1),key="task11-b3-lifecycle-resubmit-"+n;var found=receipts.stream().filter(row->task.equals(row.get("result_id"))&&"PUBLICATION_RESUBMIT".equals(row.get("operation"))).toList();assertEquals(1,found.size());receipt(found.getFirst(),owner,meeting,task,key,202);var sub=Task11B3LocalOracle.row(after,"publication_submission","task_id",task);assertEquals(Task11B3LocalOracle.digest(publication,"13",Integer.toString(5+2*n),(String)sub.get("confirmation_id"),(String)sub.get("provider_id"),(String)sub.get("library_id"),(String)sub.get("folder_id")),found.getFirst().get("request_hash"));}
  for(int n:List.of(1,2,5)){String task=tasks.get(n-1),key="task11-b3-lifecycle-local-"+n;var found=receipts.stream().filter(row->task.equals(row.get("result_id"))&&"PUBLICATION_LOCAL_RECOVERY".equals(row.get("operation"))).toList();assertEquals(1,found.size());receipt(found.getFirst(),owner,meeting,task,key,200);assertEquals(Task11B3LocalOracle.digest(publication,task,"13",Integer.toString(6+2*n)),found.getFirst().get("request_hash"));}
 }
 static void receipt(Map<String,Object> row,String owner,String meeting,String task,String key,int status)throws Exception {assertEquals(owner,row.get("actor_id"));assertEquals(meeting,row.get("resource_id"));assertEquals(task,row.get("result_id"));assertEquals("SUCCEEDED",row.get("state"));assertEquals(java.math.BigInteger.valueOf(status),integer(row.get("http_status")));assertEquals(Task11B3LocalOracle.digest(key),row.get("key_hash"));assertEquals(Task11B3LocalOracle.digest(owner,meeting,(String)row.get("operation"),key),row.get("scope_hash"));assertNotNull(row.get("created_at"));}
 record Sealed(String task,String execution,Map<String,List<Map<String,Object>>> rows){}
 static final Set<String> CLOSED_TABLES=Set.of("durable_task","external_execution","publication_submission","task_attempt","publication_attempt"),APPEND_ONLY=Set.of("audit_event","idempotency_record","task_outbox");
 static List<Map<String,Object>> selected(Map<String,List<Map<String,Object>>> rows,String table,String task,String execution){return rows.get(table).stream().filter(row->switch(table){case "durable_task"->task.equals(row.get("id"));case "external_execution"->execution.equals(row.get("id"));case "publication_submission","task_attempt"->task.equals(row.get("task_id"));case "publication_attempt"->execution.equals(row.get("execution_id"));default->true;}).toList();}
 @SuppressWarnings("unchecked") static Sealed seal(Map<String,List<Map<String,Object>>> rows,Map<String,List<String>> keys,String task,String execution){
  var t=Task11B3LocalOracle.row(rows,"durable_task","id",task);assertEquals("FAILED",t.get("state"));assertNull(t.get("lease_owner"));assertNull(t.get("expires_at"));var e=Task11B3LocalOracle.row(rows,"external_execution","id",execution);assertEquals(task,e.get("task_id"));assertEquals("FAILED",e.get("state"));assertEquals("NOT_SENT",e.get("no_effect_basis"));var sub=Task11B3LocalOracle.row(rows,"publication_submission","task_id",task);assertEquals("NEVER_MARKED",sub.get("local_state"));assertEquals(execution,sub.get("local_execution_id"));var copy=new TreeMap<String,List<Map<String,Object>>>();var tables=new HashSet<>(CLOSED_TABLES);tables.addAll(APPEND_ONLY);for(String table:tables){var captured=selected(rows,table,task,execution).stream().map(row->(Map<String,Object>)canonical(row)).toList();for(var row:captured)Task11B3LocalOracle.identity(row,keys.get(table));copy.put(table,captured);}return new Sealed(task,execution,Collections.unmodifiableMap(copy));
 }
 static void requireSealed(Sealed sealed,Map<String,List<Map<String,Object>>> rows,Map<String,List<String>> keys){
  var tables=new HashSet<>(CLOSED_TABLES);tables.addAll(APPEND_ONLY);assertEquals(tables,sealed.rows().keySet());for(String table:tables){var found=selected(rows,table,sealed.task(),sealed.execution());var actual=new HashMap<List<Object>,Map<String,Object>>();for(var row:found)assertNull(actual.put(Task11B3LocalOracle.identity(row,keys.get(table)),row));if(CLOSED_TABLES.contains(table))assertEquals(sealed.rows().get(table).size(),actual.size(),table+" sealed exact row count");for(var old:sealed.rows().get(table)){var now=actual.get(Task11B3LocalOracle.identity(old,keys.get(table)));assertNotNull(now,table+" sealed row missing");equal(old,now);}}
 }
}